package com.singtel.promotionservice;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static com.singtel.promotionservice.Lifecycle.Status.*;class LifecycleTest{@Test void creatorCannotApprove(){assertThrows(com.singtel.platformcommon.DomainError.class,()->Lifecycle.check(PENDING_APPROVAL,APPROVED,"creator","creator"));}@Test void draftCannotActivate(){assertThrows(com.singtel.platformcommon.DomainError.class,()->Lifecycle.check(DRAFT,ACTIVE,"creator","admin"));}@Test void validApproval(){assertDoesNotThrow(()->Lifecycle.check(PENDING_APPROVAL,APPROVED,"creator","approver"));}@Test void retiredIsTerminal(){for(var status:Lifecycle.Status.values())assertThrows(com.singtel.platformcommon.DomainError.class,()->Lifecycle.check(RETIRED,status,"a","b"));}}